// Packages: AWSSDK.SimpleSystemsManagement, Amazon.SimpleSystemsManagement
using Amazon.SimpleSystemsManagement;
using Amazon.SimpleSystemsManagement.Model;

public class ParameterStoreService
{
    private readonly IAmazonSimpleSystemsManagement _ssmClient;

    public ParameterStoreService(IAmazonSimpleSystemsManagement ssmClient)
    {
        _ssmClient = ssmClient;
    }

    public async Task<string> GetParameterAsync(string parameterName, bool withDecryption = true, CancellationToken cancellationToken = default)
    {
        try
        {
            var request = new GetParameterRequest
            {
                Name = parameterName,
                WithDecryption = withDecryption
            };

            GetParameterResponse response = await _ssmClient.GetParameterAsync(request, cancellationToken);
            string value = response.Parameter.Value;
            Console.WriteLine($"Parameter {parameterName} = {value}");

            return value;
        }
        catch (AmazonSimpleSystemsManagementException ex)
        {
            Console.WriteLine($"SSM error for {parameterName}: {ex.Message}");
            throw;
        }
    }
}

